fn main() -> io::Result<()>{

    let mut buffer = String::new();
    io::stdin().read_line(&mut buffer)?;

    let split: Vec<&str> = buffer.split_ascii_whitespace().collect();
    let N: usize = split[0].parse().unwrap();
    let K: usize = split[1].parse().unwrap();
    let S: usize = split[2].parse().unwrap();

    let max= 1000000000usize;

    if S == max {
        for i in 0..N {
            if i < K {
                print!("{} ", S);
            } else {
                print!("{} ", 1);
            }
        }
        return Ok(())
    }
    if S == 1 {
        for i in 0..N {
            if i < K {
                print!("{} ", 1);
            } else {
                print!("{} ", max);
            }
        }
        return Ok(())
    }

    if K == 0 {
        for i in 0..N {
            print!("{} ", max);
        }
        return Ok(())
    }

    if K == N {
        for i in 0..N {
            print!("{} ", S);
        }
        return Ok(())
    }

    for i in 0..N {
        if i < K-1 {
            print!("{} ", S);
        } else if i == K-1 {
            print!("{} ", S-1)
        } else if i == K {
            print!("{} ", 1);
        } else {
            print!("{} ", max);
        }
    }
    Ok(())
}

