    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int num = Integer.parseInt(in.next());
        int first = Integer.parseInt(in.next());
        List<Integer> pos = new ArrayList<>();
        for (int i = 0; i < num; i++) {
            pos.add(Integer.parseInt(in.next()) - first);
        }
        in.close();
        Collections.sort(pos);

        List<Integer> diff = new ArrayList<>();
        for (int i = 0; i < num-1; i++) {
            diff.add(pos.get(i + 1) - pos.get(i));
        }
        if (num == 1) diff.add(Math.abs(pos.get(0)));
        Collections.sort(diff);

        int min = diff.get(0);
        int divisor = 2;
        boolean isFound = num == 1;
        table:
        while (!isFound) {
        	for(int i = 0; i < num; i++) {
        		if ( pos.get(i) % min != 0 ) {
        			break;
        		}
        		if (i == num - 1) break table;
        	}
        	if (min % divisor == 0) {
        		min /= divisor;
        	} else {
        		boolean bool = true;
        		while (bool) {
	        		if (divisor == 2) {
	        			divisor++;
	        		} else {
	        			divisor += 2;
	        		}
	        		if (min % divisor == 0) {
	        			min /= divisor;
	        			bool = false;
	        		}
        		}
        	}
        }
        System.out.println(min);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        char[] c = sc.next().toCharArray();
        int[] currency = new int[c.length+1];
        int ans = 0;
        int borrow = 0;
        int tmp = 0;
        for(int i=c.length-1;i>=0;i--){
            tmp = c[i]-'0'+borrow;
            if(tmp < 5){
                currency[i+1] = tmp;
                ans+=tmp;
                borrow = 0;
            }else if(tmp == 5){
                if(i>=1 && c[i-1] >='5'){
                    borrow = 1;
                }else{
                    currency[i+1] = tmp;
                    borrow = 0;
                    ans+=tmp;
                }
            }else if(tmp<=9){
                borrow = 1;
            }else if(tmp==10){
                borrow = 1;
            }
        }
        if(borrow==1){
            ans++;
            currency[0] = 1;
        }
        borrow = 0;
        for(int i=c.length-1;i>=0;i--){
            tmp = currency[i+1] - (c[i] - '0') - borrow;
            if(tmp < 0){
                tmp  = tmp + 10;
                borrow = 1;
            }else{
                borrow = 0;
            }
            ans+=tmp;
        }
        System.out.println(ans);
    }
}

