func solution(n, k, s int) []int {
	ans := make([]int, n)
	for i := 0; i < k; i++ {
		ans[i] = s
	}
	if s == 1e9 {
		for i := k; i < n; i++ {
			ans[i] = 1
		}
	} else {
		for i := k; i < n; i++ {
			ans[i] = s + 1
		}
	}

	return ans
}

