		}
		else if (a[i] == 5 && a[i - 1] >= 5)
		{
			a[i - 1]++;
			ans += 5;
		}
		else
			ans += a[i];
	}
	while (a[0] > 0)
	{
		if (a[0] % 10 > 5)
		{
			ans += 10 - a[0] % 10;
			a[0] = a[0] / 10 + 1;
		}
		else if (a[0] == 5 && a[0] / 10 % 10 >= 5)
		{
			ans += 5;
			a[0] = a[0] / 10 + 1;
		}
		else
		{
			ans += a[0] % 10;
			a[0] /= 10;
		}
	}
