    let x: i32 = read();
    assert!(1 <= x && x <= 10000);
    let mut l_list: Vec<i32> = Vec::new();

    for _ in 0..n {
        l_list.push(read());
    }
    l_list.iter().map(|&l| {
        assert!(1 <= l && l <= 100)
    });
    let mut count: usize = 0;
    let mut d: i32 = 0;

    loop {
        if count == (n + 1){
            break;
        }

        if count > 0 {
            d += *l_list.get(count - 1).unwrap();
        }

        if d > x {
            break;
        }
        count += 1;
    }
    println!("{}", count);
}

