enum Node {
    Null,
    Ng,
    D(usize),
}

fn main() {
    use Node::*;
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut iter = s.split_whitespace();
    let (n, m): (usize, usize) = parse!(iter, 2);
    let mut v: Vec<_> = iter
        .next()
        .unwrap()
        .chars()
        .map(|x| if x == '0' { Null } else { Ng })
        .collect();
    v[n] = D(0);
    let mut r = n - 1;
    for i in 0..n {
        if let D(cur) = v[n - i] {
            if i + r <= n {
                for j in (n - i - r)..(m + 1) {
                    if i + j <= n {
                        let k = n - i - j;
                        v[k] = match v[k] {
                            Null => D(cur + 1),
                            x => x,
                        };
                        if k > 0 {
                            r = k - 1;
                        }
                    }
                }
            }
        }
    }
    let mut curi = 0;
    let mut cur = match v[0] {
        D(d) => d,
        _ => {
            println!("{}", -1);
            return;
        }
    };
    let mut ret: Vec<usize> = vec![];
    while curi < n {
        for next in (curi + 1)..(n + 1) {
            match v[next] {
                D(d) if d < cur => {
                    ret.push(next - curi);
                    curi = next;
                    cur = d;
                    break;
                }
                _ => {}
            }
        }
    }
    println!(
        "{}",
        ret.iter()
            .map(|&x| x.to_string())
            .collect::<Vec<_>>()
            .join(" ")
    ); // debug
}

