	var n, x, ans int
	fmt.Scan(&n, &x)
	cities := make([]int, n+1)
	cities[0] = x
	for i:=1; i<n+1; i++{
		fmt.Scan(&cities[i])
	}
	sort.Ints(cities)
	dis := make([]int, n)
	for i:=0; i<n; i++{
		dis[i] = cities[i+1] - cities[i]
	}
	ans = dis[0]
	for i:=1; i<n; i++{
		ans = gcd(ans, dis[i])
	} 
	fmt.Println(ans)
}

