            tmp = c[i]-'0'+borrow;
            if(tmp < 5){
                currency[i+1] = tmp;
                ans+=tmp;
                borrow = 0;
            }else if(tmp == 5){
                if(i>=1 && c[i-1] >='5'){
                    borrow = 1;
