func solution(X int, Y int) string {
	var retVal string
	if X >= Y {
		retVal = "No"
	} else {
		if Y%2 == 1 {
			retVal = "No"
		} else {
			if X*2 <= Y && Y <= X*4 {
				retVal = "Yes"
			} else {
				retVal = "No"
			}
		}
	}
	return retVal
}

