    }
    let u = ((b - a) - 1) / 2;
    if 1 + u == b - a - u {
        ans = std::cmp::min(ans, a + u);
    }
    let v = (n - (a + (n - b + 1))) / 2;
    if a + (n - b + 1) + v == n - v {
