let rec modpow a n =
  if n = 0 then 1
  else if n mod 2 = 1 then a *@ modpow a (n-1)
  else let h = modpow a (n/2) in h *@ h
let modinv a = modpow a (modulo - 2)

let fact =
  let arr = Array.init limit Fun.id in
  arr.(0) <- 1;
  for i = 1 to limit-1 do arr.(i) <- i *@ arr.(i-1); done;
  arr

let inv_fact = Array.map modinv fact

let comb n k = fact.(n) *@ inv_fact.(k) *@ inv_fact.(n-k)

