		    if(list.get(i-1) == 1){
		        Integer[] edge = {1, v, e};
		        e++;
		        result.add(edge);
		    }else{
		        for(Integer[] edge : result){
		            edge[2] *= 2;
		        }
		        Integer[] edge0 = {v, v+1, 0};
		        Integer[] edge1 = {v, v+1, 1};
		        v++;
		        e *= 2;
		        result.add(edge0);
		        result.add(edge1);
		    }
		}

		// 出力
		System.out.println(v + " " + result.size());
