fn main(){
	input! {
		n: i32,
		m: i32,
		a: [i64; n],
	}
	let mut que = BinaryHeap::new();
	for i in 0..a.len() {
		que.push(a[i]);
	}
	for _ in 0..m {
		match que.pop() {
			Some(ref mut ai) => {
				*ai /= 2;
				que.push(*ai);
			},
			_ => {}
		}
	}
	let mut ans: i64 = 0;
	while !que.is_empty() {
		match que.pop() {
			Some(ai) => {
				ans += ai;
			},
			_ =>  {}
		}
	}
	println!("{}", ans);
}

