(function(input){
  input=input.trim().split(/\s+/).map(x=>x-0);
  const N=input.shift(),
        K=input.shift(),
        P=1e9+7;
  function Node(){
    let t=this;
    t.children=[];
    t.height=0;
  }
  const nodes=new Array(N+1).fill(0).map(z=>new Node());
  nodes[0].children.push(nodes[1]);
  nodes[1].children.push(nodes[0]);
  while(input.length){
    let u=input.pop(),
        v=input.pop();
    nodes[u].children.push(nodes[v]);
    nodes[v].children.push(nodes[u]);
  }
  const stack=[nodes[0]];
  while(stack.length){
    let t=stack[stack.length-1];
    stack.pop();
    t.children.forEach(function(c){
      let cc=c.children;
      c.height=t.height+1;
      cc.splice(cc.indexOf(t),1);
      stack.push(c);
    });
  }
  let ans=1;
  stack.push(nodes[0]);
  while(stack.length){
    let t=stack[stack.length-1];
    stack.pop();
    if(t.height<2){
      for(let i=0,I=t.children.length;i<I;i++){
        if(ans*(K-t.height-i)<=0){
          console.log(0);
