    public static class ABC108D
    {
        static public void Main(string[] args)
        {
            var L = int.Parse(Console.ReadLine());
            var path = new List<string>();
            var stack = new Stack<int>();
            var sum = 1;
            var i = 1;
            for (; i <= 20; i++)
            {
                if ((L & 1) == 1) stack.Push(i);
                L >>= 1;
                if (L == 0) break;
                path.Add(i + " " + (i + 1) + " " + 0);
                path.Add(i + " " + (i + 1) + " " + sum);
                sum <<= 1;
            }
            stack.Pop();
            while (stack.Count > 0)
            {
                var idx = stack.Pop();
                path.Add(idx + " " + i + " " + sum);
                sum += Enumerable.Repeat(2, idx - 1).Aggregate(1, (x, y) => x * y);
            }
            Console.WriteLine(i + " " + path.Count);
            path.ForEach(Console.WriteLine);
        }
    }
}

