package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
)

const (
	BUFSIZE   = 10000000
	MOD       = 1000000007
	INF_INT   = math.MaxInt32
	INF_INT64 = math.MaxInt64
)

var rdr *bufio.Reader

func main() {
	rdr = bufio.NewReaderSize(os.Stdin, BUFSIZE)
	solve()
}

func solve() {
	var N, M int
	fmt.Scanf("%d %d", &N, &M)
	A := readIntSlice(N)
	h := &IntHeap{}
	for _, a := range A {
		heap.Push(h, -a)
	}

	for i := 0; i < M; i++ {
		item := heap.Pop(h)
		heap.Push(h, item.(int)/2)
	}

	ans := 0
	for h.Len() != 0 {
		ans -= heap.Pop(h).(int)
	}
	fmt.Println(ans)
}

func readline() string {
	buf := make([]byte, 0, BUFSIZE)
	for {
		l, p, e := rdr.ReadLine()
		if e != nil {
			fmt.Println(e.Error())
			panic(e)
		}
		buf = append(buf, l...)
		if !p {
			break
		}
	}
	return string(buf)
}

