	for (n = 1; n * n < N; n *= 2);
	if (n * n - N > N - (n-1) * (n-1)) {
		for (n /= 2; n * n < N; n++);
		for (; N % n != 0; n--);
	} else {
		for (; n * n > N; n--);
		for (; N % n != 0; n--);
	}	

	printf("%lld\n", n + N / n - 2);
	fflush(stdout);
	return 0;
}

