package main

import (
	"bufio"
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	stdin := bufio.NewScanner(os.Stdin)
	for stdin.Scan() {
		in := stdin.Text()
		out, _ := do(in)
		fmt.Println(out)
	}

}

func do(in string) (string, error) {
	s := strings.Split(in, " ")
	if len(s) != 3 {
		return "", errors.New("len")
	}
	table, err := strconv.ParseUint(s[0], 10, 64)
	if err != nil {
		return "", errors.New("table")
	}
	a, err := strconv.ParseUint(s[1], 10, 64)
	if err != nil {
		return "", errors.New("a")
	}
	b, err := strconv.ParseUint(s[2], 10, 64)
	if err != nil {
		return "", errors.New("b")
	}

	if (a%2 == 0 && b%2 == 0) || (a%2 == 1 && b%2 == 1) {
		return strconv.FormatUint((b-a)/2, 10), nil
	}

	var A, B uint64
	if table-b < a {
		A = table - b
		B = table - a
	} else {
		A, B = a-1, b-1
	}

	return strconv.FormatUint((((B - A + 1) / 2) + A), 10), nil
}

