	fmt.Scan(&l)

	var n int
	for i := 1; pow(i)-1 < l; i++ {
		n = i
	}

	maxWeights := pow(n) - 1
	var lines []line
	for i := n - 1; i >= 0; i-- {
		weight := pow(i) - 1
		newWeigts := (maxWeights + 1) + weight
		if newWeigts < l {
			lines = append(lines, line{from: i, weight: maxWeights + 1})
			maxWeights = newWeigts
		}
	}

