namespace AtCoder.ABC141
{
    class QuestionD
    {
        public static void Main(string[] args)
        {
            // 文字列配列の入力
            var inputIntArray1 = Console.ReadLine().Split(' ').Select(i => int.Parse(i)).ToArray();
            int n = inputIntArray1[0];
            int m = inputIntArray1[1];

            // 整数配列の入力
            var aArray = Console.ReadLine().Split(' ').Select(i => long.Parse(i)).ToArray();

            List<long>[] groups = new List<long>[32];
            for(int i = 0; i < 32; i++)
            {
                groups[i] = new List<long>();
            }

            //すべての数字をバイト列に変換し、長さごとにグループ化する
            for(int i = 0; i < n; i++)
            {
                var b = Convert.ToString(aArray[i], 2);
                groups[b.Length].Add(aArray[i]);
            }

            for(int i = 31; i >= 0; i--)
            {
                if (m == 0)
                {
                    //割引券がなくなったら終わり
                    break;
                }

                var list = groups[i];
                if(list.Count() == 0)
                {
                    continue;
                }
                if(list.Count <= m)
                {
                    //一番大きいグループ全部に割引券を使える
                    m -= list.Count;
                    if (i != 0)
                    {
                        foreach (var b in list)
                        {
                            groups[i - 1].Add(b >> 1);
                        }
                    }
                    groups[i] = null;
                }
                else
                {
                    //このグループの中身をソートして、高いものだけシフト演算
                    var tmp = list.OrderBy(l => l).ToList();
                    for(int j = 0; j < m; j++)
                    {
                        //クーポンの枚数だけ、末尾を移していく
                        var index = tmp.Count() - 1;
                        var item = tmp[index];
                        if(i != 0)
                        {
                            groups[i - 1].Add(item >> 1);
                        }
                        tmp.RemoveAt(index);
                    }
                    groups[i] = tmp;
                    m = 0;
                }
            }


            long result = 0;
            //全部足す
            foreach(var group in groups)
            {
                if(group == null)
                {
                    break;
                }
                foreach(var item in group)
                {
                    result += item;
                }
            }

            Console.WriteLine(result);
        }
    }
}

