			//色の組み合わせ。
			if (i == 0) {
				if (k == n - 1) {
					colorPattern[k - i] = m;
				} else {
					colorPattern[k - i] = (pattern * (m - 1)) % limit;
				}
			} else {
				colorPattern[k - i] = (colorPattern[k - i + 1] * (m - 1)) % limit;
			}
		}

		long countPattern = 0;
		for (int i = 0; i <= k; i++) {
			countPattern = (countPattern + (nextPattern[i] * colorPattern[i]) % limit) % limit;
		}

		// 出力
		System.out.println(countPattern);
		sc.close();
	}

	//モジュラ逆数
	public static int modinv(int a, int m) {
		int tempA = a;
		int tempB = m;
		int x0 = 1;
		int y0 = 0;
		int x1 = 0;
		int y1 = 1;
		while (tempB != 0) {
			int q = tempA / tempB;
			int temp = tempA;
			tempA = tempB;
			tempB = temp % tempB;
			temp = x0;
			x0 = x1;
			x1 = temp - q * x1;
			temp = y0;
			y0 = y1;
			y1 = temp - q * y1;
		}
		return x0 % m;
	}
}

