def main():
    nn = n = input()
    if n == 1:
        print(0)
        return
    factors = {}
    p = 2
    while n % p == 0:
        factors[p] = factors.get(p, 0) + 1
        n //= p
    p = 3
    while nn >= p * p:
        while n % p == 0:
            factors[p] = factors.get(p, 0) + 1
            n //= p
        p += 2
    if n > 1:
        factors[n] = factors.get(n, 0) + 1

    s = []
    for f in factors:
        n = factors[f]
        s.append([(f ** i, f ** (n - i)) for i in xrange(n + 1)])

    best = float('inf')
    for case in product(*s):
        a = b = 1
        for aa, bb in case:
            a *= aa
            b *= bb
        best = min(best, a + b - 2)
    print(best)


