class Program
{
    static void Main(string[] args)
    {
        var num = ToInt32(ReadLine());
        var abc = new int[num][];
        for (var i = 0; i < num; i++)
            abc[i] = Array.ConvertAll(ReadLine().Split(' '), int.Parse);
        var dp = new int[num,3,3];
        for(var j = 0; j < 3; j++)
        {
            for (var h = 0; h < 3; h++)
                dp[0, j, h] = abc[0][j];
        }
        for (var i = 1; i < num; i++)
        {
            for(var j = 0; j < 3; j++)
            {
                for(var h = 0; h < 3; h++)
                {
                    if (j == h) { dp[i, j, h] = 0; continue; }
                    var m = 0;
                    for(var w = 0; w < 3; w++)
                    {
                        if (w == j) continue;
                        for (var q = 0; q < 3; q++)
                            m = Max(m, dp[i - 1, w, q]);
                    }
                    dp[i, j, h] = abc[i][j] + m;
                }
            }
        }
        var max = 0;
        for (var i = 0; i < 3; i++)
            for (var j = 0; j < 3; j++)
                max = Max(max, dp[num - 1, i, j]);
        WriteLine(max);
    }
