            N = B;
        }

        long max = -1;
        for (long x = N; x >= 0; x--) {
            if (x < B - 1 && max != -1) {
                break;
            }
            long letMax = (long) (A * x / B) - A * (long) (x / B);
            if (letMax >= max) {
                max = letMax;
            }
        }

