        c[i]=c[i-1]*(n-i)as u64%MOD*y%MOD;
    }
    let mut p=vec![0;n];
    p[0]=m;
    for i in 1..n {
        p[i]=p[i-1]*(m-1)%MOD;
    }
    let mut t=0;
    for i in 0..=k {
        t = (t+c[i]*p[n-i-1]%MOD)%MOD;
    }
    println!("{}",t);
}
